#!/bin/bash
# Generated by multirepo-adapter — deterministic grader for the SEPARATE verifier.
# Computes the two deterministic reward channels the Pod Guide requires:
#   outcome     — per-repo FAIL_TO_PASS ∧ PASS_TO_PASS gate (0.0|1.0)
#   constraints — external (read-only) repos untouched ∧ test files untampered
#                 ∧ no forbidden strings
# and writes three artifacts to /logs/verifier:
#   outcome.json  — RED/GREEN proof blob (resolved / all_f2p_green / all_p2p_green / constraints)
#   reward.json   — {"reward": <outcome>, ...}; pod5_evalkit reads this as the outcome channel
#   reward.txt    — the pure outcome scalar (Harbor / passk_reduce contract)
# The test runner is dispatched by the F2P/P2P test-id EXTENSION (go/java/node/py),
# so a Go/Java/TS task is graded with go test / mvn / vitest|jest — not pytest.
# The declared FAIL_TO_PASS / PASS_TO_PASS ids come from /tests/config.json — the
# single grader config (bundle test_config.json ∪ instance.json ∪ the repo plan).
set -uo pipefail

WORKSPACE_ROOT="${WORKSPACE_ROOT:-/workspace}"
WORKDIR="$WORKSPACE_ROOT/pd"   # pd is relative to WORKSPACE_ROOT
mkdir -p /logs/verifier

# Which of the two graded-test-patch apply paths actually ran. There are two
# (git apply, then a `patch -F0` fallback), and a submission can apply cleanly
# under one and reject under the other — so the score is only interpretable if
# the path is recorded. Group V (V1) asserts parity across both.
apply_path="none"

# Per-test verdicts accumulate here as `id<TAB>status` lines. Truncated up
# front and next to apply_path so the EXIT trap can name it unconditionally:
# a trap that fires before the runners ever start finds an empty file and
# write_reward omits the map, which is the fallback-to-scalar path.
PER_TEST=/logs/verifier/per_test.tsv
: > "$PER_TEST"

write_reward() {  # args: outcome f2p p2p constraints apply_path per_test_tsv
  python3 - "$@" <<'PY'
import json, sys
outcome, f2p, p2p, constraints = float(sys.argv[1]), sys.argv[2] == "1", sys.argv[3] == "1", float(sys.argv[4])
apply_path = sys.argv[5] if len(sys.argv) > 5 else "none"

# Per-test verdicts, id -> status. Harbor's declared_tests channel scores the
# FRACTION of FAIL_TO_PASS that passed (with PASS_TO_PASS still an absolute
# veto), which it can only do from this map; without it the scalar below is
# all it has and the score collapses to 0.0|1.0. Emitted only when non-empty:
# an empty map is not "everything failed", it is "we never got far enough to
# run anything", and the harness must fall back to the scalar there.
tests = {}
per_test = sys.argv[6] if len(sys.argv) > 6 else ""
if per_test:
    try:
        with open(per_test) as fh:
            for line in fh:
                tid, _, status = line.rstrip("\n").partition("\t")
                if tid and status:
                    tests[tid] = status
    except OSError:
        pass

resolved = outcome >= 1.0
blob = {
    "outcome": outcome, "resolved": resolved,
    "all_f2p_green": f2p, "all_p2p_green": p2p,
    "reference_ok": resolved, "constraints": constraints,
    "aggregate_deterministic": outcome,
    "test_patch_apply_path": apply_path,
    "tests": tests,
}
reward = {
    "reward": outcome, "outcome": outcome, "constraints": constraints,
    "resolved": int(resolved), "all_f2p_green": int(f2p),
    "all_p2p_green": int(p2p), "reference_ok": int(resolved),
    "test_patch_apply_path": apply_path,
    "tests": tests,
}
# Written as a literal key above so `harbor tasks doctor` can see it in this
# source, but dropped when empty: an empty map is not "every test failed", and
# the harness must fall back to the scalar rather than score a run that never
# reached the runners.
if not tests:
    del blob["tests"], reward["tests"]
json.dump(blob, open("/logs/verifier/outcome.json", "w"), indent=2)
json.dump(reward, open("/logs/verifier/reward.json", "w"), indent=2)
open("/logs/verifier/reward.txt", "w").write(f"{outcome}\n")
print("[outcome.json]", json.dumps(blob))
PY
}
# Guarantee reward artifacts even on early failure (Harbor errors without one).
trap 'write_reward "${outcome:-0}" "${f2p:-0}" "${p2p:-0}" "${constraints:-0}" "${apply_path:-none}" "${PER_TEST:-}"' EXIT

# ── language-aware test runner: dispatch by the test id's file extension ──
_file_of() { printf '%s' "${1%%::*}"; }
_name_of() { printf '%s' "${1##*::}"; }

_maven_module() {  # nearest ancestor dir (relative to WORKDIR) containing pom.xml
  local d; d="$(dirname "$1")"
  while [ "$d" != "." ] && [ "$d" != "/" ] && [ -n "$d" ]; do
    [ -f "$WORKDIR/$d/pom.xml" ] && { printf '%s' "$d"; return; }
    d="$(dirname "$d")"
  done
  printf ''
}

# ── no-match guard ──────────────────────────────────────────────────────────
# Every selector-based runner below shares one failure mode: a filter that
# matches NOTHING exits 0. `go test -run NoSuchTest` is "ok, 0 tests"; jest/
# vitest -t with no match reports 0 run and exits 0; `cargo test -- name` with
# no match is a clean pass; surefire's failIfNoSpecifiedTests=false makes that
# behaviour explicit. For a FAIL_TO_PASS set that is a FALSE GREEN — the task
# scores 1.0 without the fix ever being written, which is strictly worse than a
# crash because nothing looks wrong. So each runner must prove a test actually
# executed, not merely that the command was happy.
#
# _guard <must-match-regex> -- <command...>  : run, echo output, fail unless the
# command succeeded AND its output shows at least one test running.
_guard() {
  local must="$1"; shift; [ "$1" = "--" ] && shift
  local out st
  out="$("$@" 2>&1)"; st=$?
  printf '%s\n' "$out"
  if [ $st -ne 0 ]; then return 1; fi
  if ! printf '%s' "$out" | grep -qE "$must"; then
    echo "NO-MATCH-GUARD: '$*' exited 0 but no test appears to have run;" >&2
    echo "  treating as FAILURE (a non-matching selector must never score GREEN)." >&2
    return 1
  fi
  return 0
}

_go_pkg() {  # id's file part -> the package spec to hand `go test`
  local f="$1"
  case "$f" in
    # A real .go file: the package is its directory.
    *.go) printf './%s' "$(dirname "$f")" ;;
    *)
      # Otherwise the id names a PACKAGE, not a file — the common form in these
      # bundles (`pkg/cmd/render::Test_x`, `client::TestIntegration/...`,
      # `github.com/opencontainers/runc/libcontainer/specconv::TestX`). A
      # dotted first segment means a full import path; anything else is a
      # module-relative dir and needs the ./ prefix or go treats it as a path
      # in GOPATH mode.
      case "${f%%/*}" in
        *.*) printf '%s' "$f" ;;
        *)   printf './%s' "$f" ;;
      esac ;;
  esac
}

_go_re() {  # test name -> anchored -run regex, honouring subtests
  # `go test -run` splits its pattern on / and applies each element to the
  # corresponding test level, so a subtest id must become `^Parent$/^Child$`.
  # Emitting `^(Parent/Child)$` (the old form) matches NOTHING, which combined
  # with go's exit-0-on-no-match is a silent false GREEN.
  local n="$1" out="" part IFS=/
  for part in $n; do out="$out/^${part}\$"; done
  printf '%s' "${out#/}"
}

_run_go() {
  local id rc=0
  # Group by package. Plain (non-subtest) names in a package share one `go test`
  # invocation via ^(A|B|C)$; subtest ids must each carry their own pattern.
  local pkgs=()
  for id in "$@"; do pkgs+=("$(_go_pkg "$(_file_of "$id")")"); done
  local upkgs; upkgs="$(printf '%s\n' "${pkgs[@]}" | sort -u)"

  local pkg
  for pkg in $upkgs; do
    local plain=() subs=() n
    for id in "$@"; do
      [ "$(_go_pkg "$(_file_of "$id")")" = "$pkg" ] || continue
      n="$(_name_of "$id")"
      case "$n" in */*) subs+=("$n") ;; *) plain+=("$n") ;; esac
    done
    local patterns=()
    if [ "${#plain[@]}" -gt 0 ]; then
      local nre; nre="$(printf '%s|' "${plain[@]}")"; patterns+=("^(${nre%|})\$")
    fi
    for n in ${subs[@]+"${subs[@]}"}; do patterns+=("$(_go_re "$n")"); done
    # Resolve the Go module that owns this package. Go does not descend into
    # nested modules, so a package under a sub-module (e.g. client/ with its own
    # go.mod) must be tested from that module's root, not $WORKDIR — otherwise
    # `go test ./client` from the root module matches nothing and the id is
    # silently scored a NO-MATCH failure. Walk up from the package dir to the
    # nearest go.mod at or below $WORKDIR; a single-module repo resolves to
    # $WORKDIR and the behaviour is unchanged.
    local _absdir="$WORKDIR/${pkg#./}" _moddir="$WORKDIR" _d="$WORKDIR/${pkg#./}"
    while [ "$_d" != "$WORKDIR" ] && [ "$_d" != "/" ] && [ -n "$_d" ]; do
      if [ -f "$_d/go.mod" ]; then _moddir="$_d"; break; fi
      _d="$(dirname "$_d")"
    done
    local _relpkg="./${_absdir#$_moddir/}"
    [ "$_moddir" = "$_absdir" ] && _relpkg="."
    local p out st
    for p in "${patterns[@]}"; do
      out="$( cd "$_moddir" && go test -v -run "$p" "$_relpkg" 2>&1 )"; st=$?
      printf '%s\n' "$out"
      if [ $st -ne 0 ]; then rc=1; continue; fi
      if printf '%s' "$out" | grep -q 'no tests to run'; then
        echo "NO-MATCH-GUARD: go selector '$p' matched nothing in $pkg" >&2; rc=1; continue
      fi
      printf '%s' "$out" | grep -qE '^=== RUN|^--- PASS' || {
        echo "NO-MATCH-GUARD: no go test executed for '$p' in $pkg" >&2; rc=1; }
    done
  done
  return $rc
}

_run_java() {
  local sel=() gradle_args=() module="" id
  for id in "$@"; do
    # basename -.java was wrong for Kotlin: `basename Foo.kt .java` returns
    # "Foo.kt", so -Dtest="Foo.kt#m" silently matched nothing. Strip ANY ext.
    local f cls m; f="$(_file_of "$id")"; cls="$(basename "$f")"; cls="${cls%.*}"
    m="$(_name_of "$id")"
    sel+=("${cls}#${m}")
    gradle_args+=(--tests "*.${cls}.${m}")
    [ -z "$module" ] && module="$(_maven_module "$f")"
  done
  local IFS=,; local tests="${sel[*]}"; unset IFS
  # Maven when there's a pom (possibly in a submodule); Gradle otherwise —
  # Kotlin repos are almost never Maven, and .kt maps here.
  if [ -n "$module" ] || [ -f "$WORKDIR/pom.xml" ]; then
    local pl=(); [ -n "$module" ] && pl=(-pl "$module" -am)
    # NOTE: failIfNoSpecifiedTests stays false so sibling modules pulled in by
    # -am don't fail for not containing the test; the real guard is the
    # "Tests run: N" assertion below, which is module-agnostic.
    _guard 'Tests run: [1-9]' -- env -C "$WORKDIR" \
      mvn -B -o "${pl[@]}" -Dsurefire.failIfNoSpecifiedTests=false -Dtest="$tests" test
  elif [ -f "$WORKDIR/build.gradle" ] || [ -f "$WORKDIR/build.gradle.kts" ]; then
    # The repo's own wrapper pins the version the project expects; fall back to
    # the Gradle the Dockerfile installed. --offline because the grader runs
    # with the network closed and the caches were primed at build time.
    local gcmd="gradle"
    [ -x "$WORKDIR/gradlew" ] && gcmd="./gradlew"
    _guard '[1-9][0-9]* tests? completed|BUILD SUCCESSFUL' -- env -C "$WORKDIR" \
      "$gcmd" --offline test "${gradle_args[@]}"
  else
    echo "no pom.xml / build.gradle under $WORKDIR — cannot run JVM tests" >&2
    return 2
  fi
}

_run_node() {
  local files=() names=() id
  for id in "$@"; do files+=("$(_file_of "$id")"); names+=("$(_name_of "$id")"); done
  local nre; nre="$(printf '%s|' "${names[@]}")"; nre="(${nre%|})"
  local runner
  if   [ -x "$WORKDIR/node_modules/.bin/vitest" ]; then runner="node_modules/.bin/vitest run"
  elif [ -x "$WORKDIR/node_modules/.bin/jest" ];   then runner="node_modules/.bin/jest"
  elif [ -x "$WORKDIR/node_modules/.bin/mocha" ];  then runner="node_modules/.bin/mocha"
  else runner="npx --no-install jest"; fi
  local rc=0 f
  while IFS= read -r f; do
    [ -z "$f" ] && continue
    # jest/vitest report "Tests: N passed"; mocha reports "N passing".
    _guard 'Tests?:?[^0-9]*[1-9][0-9]* (passed|passing)|[1-9][0-9]* passing|✓' \
      -- env -C "$WORKDIR" sh -c "$runner \"\$1\" -t \"\$2\"" _ "$f" "$nre" || rc=1
  done < <(printf '%s\n' "${files[@]}" | sort -u)
  return $rc
}

_run_rust() {
  local rc=0 id
  for id in "$@"; do
    local f n; f="$(_file_of "$id")"; n="$(_name_of "$id")"
    local tgt=(--lib) filt="$n"
    case "$f" in
      tests/*)
        # Cargo integration-test TARGETS are tests/<name>.rs, or the directory
        # tests/<name>/ (whose main.rs is the target root). tests/shaping/
        # custom.rs is therefore target `shaping` with `custom` as a MODULE —
        # passing `--test custom` gets "no test target named custom".
        local rest="${f#tests/}" first
        first="${rest%%/*}"
        if [ "$first" = "$rest" ]; then
          tgt=(--test "${first%.rs}")
        else
          tgt=(--test "$first")
          # Remaining path becomes the module prefix on the filter.
          local modp="${rest#*/}"; modp="${modp%.rs}"
          modp="$(printf '%s' "$modp" | sed 's#/#::#g')"
          filt="${modp}::${n}"
        fi ;;
    esac
    # --exact needs the fully-qualified path; fall back to a substring filter,
    # then to the bare name. All three are guarded, so a filter matching nothing
    # still fails rather than passing quietly.
    _guard '^test .* \.\.\. ok' -- env -C "$WORKDIR" \
        cargo test --offline "${tgt[@]}" -- --exact "$filt" \
      || _guard '^test .* \.\.\. ok' -- env -C "$WORKDIR" \
        cargo test --offline "${tgt[@]}" -- "$filt" \
      || _guard '^test .* \.\.\. ok' -- env -C "$WORKDIR" \
        cargo test --offline "${tgt[@]}" -- "$n" \
      || rc=1
  done
  return $rc
}

_c_configure() {  # make sure a build system is bootstrapped; autotools needs it
  [ -f "$WORKDIR/Makefile" ] && return 0
  ( cd "$WORKDIR" || exit 1
    if [ -f CMakeLists.txt ]; then
      cmake -S . -B build -DCMAKE_BUILD_TYPE=Debug -DCMAKE_PREFIX_PATH=/opt/crossrepo
    elif [ -f meson.build ]; then
      meson setup build
    elif [ -f configure ] || [ -f autogen.sh ] || [ -f configure.ac ]; then
      # Most autotools projects ship only configure.ac + autogen.sh in git, so
      # `configure` (and therefore Makefile) does not exist until bootstrapped.
      { [ -f configure ] || ./autogen.sh || autoreconf -fi; } && ./configure
    fi ) >/dev/null 2>&1
  return 0
}

_run_c_binaries() {
  # Plain make / autotools suites (crun, most C projects) have NO per-test
  # selector: `tests/foo.c` compiles to the executable `tests/foo`, whose main()
  # runs every case in the file. The id's ::name part identifies the function
  # for humans; the executable is the runnable unit. Build it, run it, and let
  # its exit status be the verdict.
  local rc=0 f bin out st built=0
  for f in "$@"; do
    bin="${f%.*}"
    ( cd "$WORKDIR" && make "$bin" ) >/dev/null 2>&1 \
      || ( cd "$WORKDIR" && make check ) >/dev/null 2>&1 || true
    if [ ! -x "$WORKDIR/$bin" ]; then
      echo "NO-MATCH-GUARD: no test executable at $bin after make" >&2; rc=1; continue
    fi
    built=1
    out="$( cd "$WORKDIR" && "./$bin" 2>&1 )"; st=$?
    printf '%s\n' "$out"
    [ $st -eq 0 ] || rc=1
  done
  [ "$built" = 1 ] || return 1
  return $rc
}

_run_c() {  # C and C++ share a runner: the build system, not the language, picks it
  local names=() files=() id
  for id in "$@"; do names+=("$(_name_of "$id")"); files+=("$(_file_of "$id")"); done
  local nre; nre="$(printf '%s|' "${names[@]}")"; nre="^(${nre%|})\$"
  local gre; gre="$(printf '%s:' "${names[@]}")"; gre="${gre%:}"
  local ufiles; ufiles="$(printf '%s\n' "${files[@]}" | sort -u)"
  _c_configure

  if [ -f "$WORKDIR/CMakeLists.txt" ]; then
    [ -d "$WORKDIR/build" ] || ( cd "$WORKDIR" && cmake -S . -B build \
        -DCMAKE_BUILD_TYPE=Debug -DCMAKE_PREFIX_PATH=/opt/crossrepo ) >/dev/null 2>&1
    ( cd "$WORKDIR" && cmake --build build -j"$(nproc)" ) >/dev/null 2>&1
    # 1) CTest by registered test name.
    if _guard '100% tests passed|[1-9][0-9]* +tests? +passed' -- env -C "$WORKDIR" \
         ctest --test-dir build --output-on-failure -R "$nre"; then
      return 0
    fi
    # 2) Fall back to a GoogleTest binary filter (ids like `f.cpp::Suite.Name`).
    local bin
    bin="$(find "$WORKDIR/build" -type f -perm -u+x -name '*test*' 2>/dev/null | head -1)"
    if [ -n "$bin" ]; then
      _guard '\[  PASSED  \] [1-9]' -- "$bin" --gtest_filter="$gre" && return 0
    fi
    return 1
  fi
  if [ -f "$WORKDIR/meson.build" ]; then
    _guard '[1-9][0-9]*/[0-9]+ +.*OK|Ok: +[1-9]' -- env -C "$WORKDIR" \
      meson test -C build "${names[@]}"
    return $?
  fi
  if [ -f "$WORKDIR/Makefile" ]; then
    # Prefer building and running the specific test executables named by the
    # ids; only fall back to a whole-suite `make check` if that finds nothing.
    # shellcheck disable=SC2086
    if _run_c_binaries $ufiles; then return 0; fi
    _guard 'PASS|ok|passed' -- env -C "$WORKDIR" make check
    return $?
  fi
  echo "no CMakeLists.txt / meson.build / Makefile under $WORKDIR (tried cmake, meson, autotools bootstrap)" >&2
  return 2
}

_run_php() {
  local methods=() id
  for id in "$@"; do methods+=("$(_name_of "$id")"); done
  local nre; nre="$(printf '%s|' "${methods[@]}")"; nre="${nre%|}"
  local phpunit
  if   [ -x "$WORKDIR/vendor/bin/phpunit" ]; then phpunit="vendor/bin/phpunit"
  elif command -v phpunit >/dev/null 2>&1;   then phpunit="phpunit"
  else echo "no phpunit found under $WORKDIR or in PATH" >&2; return 2; fi
  _guard 'OK \([1-9]|Tests: [1-9]' -- env -C "$WORKDIR" \
    "$phpunit" --filter "^(${nre})$"
}

# Language the adapter resolved at generate time (config.json "language").
# Used for ids that name a PACKAGE rather than a file and so carry no extension.
# Read the canonical `test_lang`, NOT `language`: the latter is the bundle's own
# spelling ("javascript", "golang") and would not match the runner names below.
TASK_LANG="$(python3 -c 'import json
try:
    c = json.load(open("/tests/config.json"))
    print(c.get("test_lang") or "")
except Exception:
    print("")' 2>/dev/null)"

_lang_of() {  # test-id file part -> logical runner (mirrors languages.py _EXT_LANG)
  case "$1" in
    *.go)                              echo go ;   return ;;
    *.java|*.kt)                       echo java ; return ;;
    *.ts|*.tsx|*.js|*.jsx|*.mjs|*.cjs) echo node ; return ;;
    *.py)                              echo python ; return ;;
    *.rs)                              echo rust ; return ;;
    *.c|*.h|*.cc|*.cpp|*.cxx|*.hpp|*.hh|*.hxx) echo c ; return ;;
  esac
  # Test the BASENAME for an extension, not the whole path: a Go import path
  # like github.com/o/r/libcontainer/specconv has dots in it but no extension.
  case "${1##*/}" in
    *.php) echo php ;;
    # An extension we don't know (.cs, .bats) is authoritative evidence
    # that this is a language we can't grade — never silently reinterpret it.
    *.*) echo unknown ;;
    # No extension at all: a package-path id. Use the task-level language.
    *)   echo "${TASK_LANG:-unknown}" ;;
  esac
}

run_ids() {  # $@ = ids "relpath::Name"; returns 0 iff all selected tests pass
  [ "$#" -eq 0 ] && return 0
  # Dispatch per language GROUP, not on the first id alone: a set mixing e.g.
  # .py and .go used to send every id to one runner, which then reported a
  # confident wrong verdict. The adapter refuses to generate mixed-language
  # tasks, but the grader must not depend on that to be correct.
  local id l rc=0 langs
  langs="$(for id in "$@"; do _lang_of "$(_file_of "$id")"; done | sort -u)"
  for l in $langs; do
    local group=()
    for id in "$@"; do
      [ "$(_lang_of "$(_file_of "$id")")" = "$l" ] && group+=("$id")
    done
    case "$l" in
      go)     _run_go     "${group[@]}" || rc=1 ;;
      java)   _run_java   "${group[@]}" || rc=1 ;;
      node)   _run_node   "${group[@]}" || rc=1 ;;
      rust)   _run_rust   "${group[@]}" || rc=1 ;;
      c)      _run_c      "${group[@]}" || rc=1 ;;
      python) python3 /tests/run_tests.py "${group[@]}" || rc=1 ;;
      php)    _run_php    "${group[@]}" || rc=1 ;;
      *) echo "unknown test id type: $(_file_of "${group[0]}")" >&2; rc=1 ;;
    esac
  done
  return $rc
}

# ── per-test attribution ──────────────────────────────────────────────────
# run_ids answers one question per SET — "did all of these pass" — because
# that is the only question `outcome` asks. The declared_tests channel asks a
# finer one, WHICH passed, and pays partial credit for a fraction of
# FAIL_TO_PASS while a single PASS_TO_PASS regression still vetoes the run.
# An id absent from the map counts as a failure there, and an absent P2P id
# therefore trips the veto, so every declared id must come away with a
# verdict — not just the interesting ones.
#
# The cost stays off the happy path. A green group means every id in it
# passed, recorded from the one runner invocation we already paid for. Only a
# RED group is re-run id-by-id, and only far enough to attribute the failure.
# Re-running in isolation can in principle disagree with the in-group verdict
# (order-dependent tests); the isolated result wins, since it is the one we
# actually observed for that id.
_mark() {  # $1 = status, $@ = ids
  local st="$1"; shift
  local id; for id in "$@"; do printf '%s\t%s\n' "$id" "$st" >> "$PER_TEST"; done
}

run_ids_scored() {  # same contract as run_ids, and records a verdict per id
  [ "$#" -eq 0 ] && return 0
  if run_ids "$@"; then _mark passed "$@"; return 0; fi
  if [ "$#" -eq 1 ]; then _mark failed "$1"; return 1; fi
  echo "[attribute] group is RED — re-running $# ids individually to attribute" >&2
  local id
  for id in "$@"; do
    if run_ids "$id"; then _mark passed "$id"; else _mark failed "$id"; fi
  done
  return 1
}

# .git was removed at build time, so we diff against the /opt/pristine snapshot of
# each repo's agent-start tree instead of git.
_pris() { printf '/opt/pristine%s' "$1"; }   # abs repo path -> pristine snapshot

# Capture the agent's real per-repo changes BEFORE touching the tree (empty in the
# standalone verifier; populated in the pod5-compiled shared run) for the out-of-band
# constraints/rubric channels.
for pair in kvproto:kvproto pd:pd; do   # name:relpath
  rname="${pair%%:*}"; rpath="$WORKSPACE_ROOT/${pair#*:}"
  [ -d "$rpath" ] && diff -ruN "$(_pris "$rpath")" "$rpath" \
    > "/logs/verifier/agent_${rname}.patch" 2>/dev/null || true
done

cd "$WORKDIR" || { echo "workspace missing: $WORKDIR"; exit 1; }

# ── constraints (pt.1): the agent must NOT have modified any F2P/P2P test file ──
# Collect test-file paths from the F2P ids and the P2P list, then flag tamper if
# the pre-injection agent diff touched any of them (before we restore them).
constraints=1.0
_cfg_ids() {  # $1/$2 = snake_case / SCREAMING_CASE key of an id list in config.json
  python3 -c 'import json,sys
c=json.load(open("/tests/config.json"))
for t in (c.get(sys.argv[1]) or c.get(sys.argv[2]) or []): print(t)' "$1" "$2"
}
mapfile -t F2P < <(_cfg_ids fail_to_pass FAIL_TO_PASS)
mapfile -t P2P < <(_cfg_ids pass_to_pass PASS_TO_PASS)

# Empty F2P is a DEFECT, not a pass: with nothing to flip RED→GREEN there is no
# task. Bail before the runner, which would otherwise report a vacuous success.
if [ "${#F2P[@]}" -eq 0 ]; then
  echo "INVALID_TASK: empty F2P set (no FAIL_TO_PASS ids in /tests/config.json)" >&2
  exit 1
fi

TEST_FILES=()
for id in "${F2P[@]}"; do TEST_FILES+=("${id%%::*}"); done
for id in "${P2P[@]:-}"; do [ -n "$id" ] && TEST_FILES+=("${id%%::*}"); done
# Also protect every file the graded test patch TARGETS, not only the files the
# declared F2P/P2P ids happen to name. test.patch routinely touches test files
# that carry no declared id; those were neither tamper-checked nor restored, so
# an agent edit to one survived into the apply step and made `git apply` and the
# `patch -F0` fallback both reject -- hard-failing the grade with ZERO tests
# executed and every channel reading 0.0, indistinguishable from a real failure.
if [ -s /tests/test.patch ]; then
  _patch_targets="$(sed -n 's|^diff --git a/\(.*\) b/.*|\1|p' /tests/test.patch | sort -u)"
  for tf in $_patch_targets; do
    case " ${TEST_FILES[*]} " in
      *" $tf "*) ;;
      *) TEST_FILES+=("$tf") ;;
    esac
  done
fi
PRIS="$(_pris "$WORKDIR")"
# Tamper = a test file the agent modified or added (differs from the pristine base).
for tf in "${TEST_FILES[@]}"; do
  if [ -e "$PRIS/$tf" ]; then
    cmp -s "$PRIS/$tf" "$WORKDIR/$tf" 2>/dev/null \
      || { echo "TAMPER: agent modified test file $tf"; constraints=0.0; }
  elif [ -e "$WORKDIR/$tf" ]; then
    echo "TAMPER: agent added test file $tf"; constraints=0.0
  fi
done

# Restore every F2P/P2P test file from the pristine snapshot (undo any tamper),
# then inject the baked F2P patch that introduces the fail-to-pass tests.
for tf in "${TEST_FILES[@]}"; do
  if [ -e "$PRIS/$tf" ]; then
    mkdir -p "$(dirname "$WORKDIR/$tf")"; cp -a "$PRIS/$tf" "$WORKDIR/$tf"
  else
    rm -f "$WORKDIR/$tf"
  fi
done
if [ -s /tests/test.patch ]; then
  # A graded test patch that does not apply must NOT degrade to a warning: grading
  # would then run against unpatched tests and emit a confident, wrong reward.
  # Hard-fail exactly like the empty-F2P guard above; the EXIT trap still writes
  # the reward artifacts (outcome 0) so Harbor never errors on a missing reward.
  # No fuzz on the graded patch — a fuzzy hunk can land in the wrong place and
  # still exit 0. -F0 keeps a fallback for whitespace-only rejects.
  # Record which path ran (V1): the two are not guaranteed to agree, and a score
  # produced by an unrecorded path cannot be reconciled after the fact.
  if git apply --whitespace=nowarn --verbose /tests/test.patch 2>&1; then
    apply_path="git-apply"
  elif patch -p1 -F0 --no-backup-if-mismatch -i /tests/test.patch 2>&1; then
    apply_path="patch-F0"
    echo "NOTE: graded test patch applied via the patch(1) fallback, not git apply" >&2
  else
    apply_path="failed"
    echo "INVALID_TASK: graded test patch failed to apply — refusing to grade against unpatched tests" >&2
    exit 1
  fi
  echo "[apply] graded test patch applied via ${apply_path}"
fi

# ── outcome: FAIL_TO_PASS then PASS_TO_PASS ──
if run_ids_scored "${F2P[@]}" > /logs/verifier/f2p.log 2>&1; then f2p=1; else f2p=0; fi

# Empty P2P is a DEFECT, not a pass: a task with no regression guard cannot ship.
if [ "${#P2P[@]}" -eq 0 ]; then
  echo "INVALID_TASK: empty P2P set (no PASS_TO_PASS regression guard)" | tee /logs/verifier/p2p.log
  p2p=0
elif run_ids_scored "${P2P[@]}" > /logs/verifier/p2p.log 2>&1; then p2p=1; else p2p=0; fi

if [ "$f2p" = 1 ] && [ "$p2p" = 1 ]; then outcome=1; else outcome=0; fi

# ── constraints (pt.2): external (read-only) repos untouched + no forbidden strings ──
for ext in "kvproto"; do   # relative to WORKSPACE_ROOT
  ext_path="$WORKSPACE_ROOT/$ext"
  diff -rq "$(_pris "$ext_path")" "$ext_path" >/dev/null 2>&1 || constraints=0.0
done
DIFF=$(diff -ruN "$PRIS" "$WORKDIR" 2>/dev/null || true)
for s in "AWS_SECRET" "BEGIN RSA PRIVATE KEY" "xoxb-" "AKIA"; do
  printf '%s' "$DIFF" | grep -q "$s" && constraints=0.0
done

echo "f2p=$f2p p2p=$p2p outcome=$outcome constraints=$constraints"
# outcome.json / reward.json / reward.txt written by the EXIT trap
